/*
 * The learner's view of their programme. Identity is the session's userId.
 * Learners never see a Step that is not shared (SCOPE), so the filter is here,
 * on the server, not in the page.
 * Which plan: the active one; with none active, the most recently started.
 * `me` carries the learner's own name, for Home's greeting (DBU-02).
 */
(async () => {
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const pick = (row, fields) => {
      const out = { id: row.objectId };
      fields.forEach((f) => { out[f] = row[f] === undefined ? null : row[f]; });
      return out;
    };

    // Who I am, for the greeting: my own name and nothing else of the account.
    const users = await q('_User', { objectId: { equalTo: me } });
    Outputs.me = { name: (users[0] && users[0].name) || '' };

    const plans = await q('Plan', { learner: { equalTo: me } });
    const active = plans.filter((p) => p.status === 'active');
    if (active.length > 1) throw new Error('more than one active plan for ' + me);
    const byStart = plans.slice().sort((a, b) => String(b.startedOn).localeCompare(String(a.startedOn)));
    const plan = active[0] || byStart[0] || null;
    if (!plan) {
      Outputs.plan = null;
      Outputs.steps = [];
      Outputs.submissions = [];
      Outputs.done();
      return;
    }

    const rows = await q('Step', { plan: { equalTo: plan.objectId } });
    const steps = rows
      .filter((s) => s.learner === me && s.shared === true)
      .sort((a, b) => a.position - b.position);
    const shared = new Set(steps.map((s) => s.objectId));
    const subs = (await q('Submission', { learner: { equalTo: me } })).filter((s) => shared.has(s.step));

    Outputs.plan = pick(plan, ['title', 'status', 'meetingLink', 'bookingLink', 'startedOn']);
    Outputs.steps = steps.map((s) => pick(s, [
      'position', 'kind', 'title', 'status', 'startsAt', 'durationMin', 'meetingLink', 'prepNote', 'attended',
      'recordingUrl', 'summary', 'dueAt', 'brief', 'handInChecklist', 'resources', 'sendsAt'
    ]));
    Outputs.submissions = subs
      .map((s) => Object.assign(pick(s, ['step', 'version', 'kind', 'files', 'url', 'text', 'note', 'review', 'reviewNote', 'reviewedAt']),
        { handedInAt: s.createdAt }))
      .sort((a, b) => a.version - b.version);
    Outputs.done();
  } catch (e) {
    console.error('[dbu:myPlan]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
